package com.lifeos.goals;import com.lifeos.goals.dto.*;import com.lifeos.shared.exception.*;import com.lifeos.users.*;import org.springframework.stereotype.Service;import java.util.*;@Service public class GoalService{private final GoalRepository r;private final UserRepository u;public GoalService(GoalRepository r,UserRepository u){this.r=r;this.u=u;}private User user(String e){return u.findByEmail(e).orElseThrow(()->new ResourceNotFoundException("User not found"));}private Goal owned(Long id,String e){return r.findByIdAndUserId(id,user(e).getId()).orElseThrow(()->new ResourceNotFoundException("Goal not found"));}public List<GoalResponse>list(String e){return r.findAllByUserIdOrderByCreatedAtDesc(user(e).getId()).stream().map(GoalResponse::from).toList();}public GoalResponse get(Long i,String e){return GoalResponse.from(owned(i,e));}public GoalResponse create(GoalRequest q,String e){Goal g=new Goal();g.setUser(user(e));apply(g,q);return GoalResponse.from(r.save(g));}public GoalResponse update(Long i,GoalRequest q,String e){Goal g=owned(i,e);apply(g,q);return GoalResponse.from(r.save(g));}public void delete(Long i,String e){r.delete(owned(i,e));}private void apply(Goal g,GoalRequest q){if(q.status()==GoalStatus.COMPLETED&&q.progress()!=100)throw new BadRequestException("Completed goals must have 100 progress");g.setTitle(q.title().trim());g.setDescription(q.description());g.setTargetDate(q.targetDate());g.setStatus(q.status());g.setProgress(q.progress());}}
